import sys

def translate_to_nimionese(sentence):
    def nearest_hard_consonant(char):
        hard_consonants = 'bcdfghjklmnpqrstvwxyz'
        index = hard_consonants.find(char.lower())
        if index == -1:
            return char
        if index == 0:
            return 'b'
        if index == len(hard_consonants) - 1:
            return 'z'
        prev_char = hard_consonants[index - 1]
        next_char = hard_consonants[index + 1]
        if abs(ord(char.lower()) - ord(prev_char)) <= abs(ord(char.lower()) - ord(next_char)):
            return prev_char
        else:
            return next_char

    def translate_word(word):
        if word.lower() == 'each':
            return 'Dach'
        first_letter = nearest_hard_consonant(word[0])
        translated_word = first_letter + word[1:].replace('b', first_letter).replace('c', first_letter).replace('d', first_letter).replace('g', first_letter).replace('k', first_letter).replace('n', first_letter).replace('p', first_letter).replace('t', first_letter)
        if translated_word[-1] in 'bcdfghjklmnpqrstvwxyz':
            translated_word += 'ah'
        return translated_word

    words = sentence.split()
    translated_words = [translate_word(word.replace('-', '')) for word in words]
    return ' '.join(translated_words)

